dtsPropsFor.GoBoard:
/** Number of lines per side (e.g. 9, 13, 19). */
  boardSize: number;
  /** Canvas render size in px. Defaults to DEFAULT_BOARD_CANVAS_SIZE. */
  boardCanvasSize?: number;
  /** Ordered moves: each is [color "B" | "W", [row, col]] or [color, null] for a pass. */
  moves: [string, [number, number] | null][];
  /** Handicap / pre-placed stones, same tuple shape as moves. */
  initialStones?: [string, [number, number] | null][];
  /** Map of move index → commentary text, keyed by 0-based move number. */
  comments: Record<number, string>;
  /** 0-based index of the move currently shown on the board. */
  currentMoveIndex: number;
  /** Advance/rewind by a signed delta (e.g. +1, -1, +5). */
  onMoveChange: (amount: number) => void;

dtsPropsFor.Controls:
/** Total number of moves in the game (upper navigation bound). */
  maxMove: number;
  /** 0-based index of the current move. */
  currentMoveIndex: number;
  /** Navigate by a signed delta (±1, ±5, or jump to either end). */
  onMoveChange: (amount: number) => void;
  /** Jump to the previous commented move. */
  onJumpToPreviousComment?: () => void;
  /** Jump to the next commented move. */
  onJumpToNextComment?: () => void;
  /** Whether an earlier commented move exists (enables the jump-back button). */
  hasPreviousCommentMove?: boolean;
  /** Whether a later commented move exists (enables the jump-forward button). */
  hasNextCommentMove?: boolean;
  /** MUI `SxProps<Theme>` overrides for the container Paper. */
  sx?: Record<string, unknown> | Record<string, unknown>[];

dtsPropsFor.CommentPanel:
/** Board canvas size in px (used to align the panel width). */
  boardCanvasSize: number;
  /** Ordered moves: [color "B" | "W", [row, col] | null]. */
  moves: [string, [number, number] | null][];
  /** 0-based index of the current move. */
  currentMoveIndex: number;
  /** Commentary text for the current move ("" when the move has none). */
  currentComment: string;
  /** Optional fixed panel height in px. */
  panelHeight?: number;

dtsPropsFor.HistoryCard:
/** A completed commentary result rendered as a summary card. */
  commentary: {
    board_size: number;
    sgf_file_name: string;
    language: "english" | "chinese (simplified)" | "japanese" | "korean";
    moves: [string, [number, number] | null][];
    initial_stones: [string, [number, number] | null][];
    comments: { turn: number; comment: string }[];
    annotated_sgf_content: string;
  };
  /** Called when the user opens this game (e.g. to view full commentary). */
  onOpen: (commentary: HistoryCardProps["commentary"]) => void;

dtsPropsFor.MiniBoardThumb:
/** Number of lines per side. */
  boardSize: number;
  /** Ordered moves: [color "B" | "W", [row, col] | null]. */
  moves: [string, [number, number] | null][];
  /** Handicap / pre-placed stones, same tuple shape as moves. */
  initialStones?: [string, [number, number] | null][];
  /** Thumbnail size in px (default 88). */
  size?: number;

dtsPropsFor.CommentaryConfig:
/** Selected Claude model id. */
  model: "claude-opus-4-8" | "claude-sonnet-4-6" | "claude-haiku-4-5";
  setModel: (value: CommentaryConfigProps["model"]) => void;
  /** Commentary output language. */
  language: "english" | "chinese (simplified)" | "japanese" | "korean";
  setLanguage: (value: CommentaryConfigProps["language"]) => void;
  /** Number of moves to annotate (1–100). */
  numComments: number;
  setNumComments: (value: number) => void;
  /** Max tokens per commentary generation call (256–8192). */
  maxToken: number;
  setMaxToken: (value: number) => void;
  /** Extra freeform instruction appended to the commentary prompt. */
  customInstruction: string;
  setCustomInstruction: (value: string) => void;
